const w = $('Webhook').first().json;
const b = w.body || w;
function f(n) { return String(b[n] || w[n] || ''); }
const text = f('text').trim().toLowerCase();
let sub = 'digest', args = '';
if (text.startsWith('help')) sub = 'help';
else if (text.startsWith('calibrate')) { sub = 'calibrate'; args = text.replace(/^calibrate\s*/, ''); }
else if (text.startsWith('target')) { sub = 'targets'; args = text.replace(/^targets?\s*/, ''); }
else if (text) { args = text; }
const region = sub === 'digest' ? args.trim().replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()) : '';
const acks = {
  digest: '\u23f3 Running Account Insights digest... Results in 1-2 minutes.',
  calibrate: '\u23f3 Running ICP Calibration \u2014 analyzing closed-won vs closed-lost accounts... Results in 3-5 minutes.',
  targets: '\u23f3 Surfacing ICP target accounts... Results in 1-2 minutes.'
};
return [{ json: {
  userId: f('user_id'), userName: f('user_name'), channelId: f('channel_id'),
  responseUrl: f('response_url'), teamDomain: f('team_domain'),
  subcommand: sub, args, sales_region: region,
  ackText: acks[sub] || acks.digest
}}];

function parseCSV(csvData) {
  if (!csvData || !csvData.trim()) return [];
  function parseLine(line) { const v=[]; let q=false,c=''; for(let i=0;i<line.length;i++){const ch=line[i]; if(ch==='"'){q=!q;continue;} if(ch===','&&!q){v.push(c.trim());c='';continue;} c+=ch;} v.push(c.trim()); return v; }
  const lines = csvData.trim().split('\n');
  const headers = parseLine(lines[0]);
  console.log('Headers:', headers.join(' | '));
  const rows = [];
  for (let i=1; i<lines.length; i++) { const v=parseLine(lines[i]); if(v.length<3)continue; const r={}; headers.forEach((h,idx)=>r[h]=v[idx]||''); rows.push(r); }
  return rows;
}
const n = s => { const x=Number(String(s||'0').replace(/[,$]/g,'')); return isFinite(x)?x:0; };

const accs = parseCSV($json.data || '');
if (!accs.length) return [{ json: { text: 'No account data.', responseUrl: $('Parse Command').first().json.responseUrl } }];

const enriched = accs.map(a => ({
  name: a['Account Name']||'?', owner: a['Account Owner (name)']||a['Account Owner (id)']||'?',
  eng: n(a['Account Engagement Level']), industry: a['Industry']||'',
  mtg30: n(a['Meetings (Last 30 Days)']), mtg7: n(a['Meetings (Last 7 Days)']),
  eS: n(a['Emails Sent (Last 30 Days)']), eR: n(a['Emails Received (Last 30 Days)']),
  ppl: n(a['People Engaged (Last 30 Days)']), execs: n(a['Executives Engaged (Last 30 Days)']),
  execActs: n(a['Activities with Executives (C-Level) (Last 30 Days)']),
  pid: a['People.ai Internal ID']||'',
  // Computed
  get emails() { return this.eS + this.eR; },
  get mtgRatio() { return this.mtg30 + this.emails > 0 ? Math.round(this.mtg30/(this.mtg30+this.emails)*100) : 0; },
  get momentum() { return this.mtg30 > 0 ? Math.round(this.mtg7 / this.mtg30 * 4.286 * 100)/100 : 0; },
  get respRate() { return this.eS > 0 ? Math.round(this.eR/this.eS*100)/100 : 0; }
}));

// Neglected: low engagement, minimal meetings
const neglected = enriched.filter(a => a.eng <= 40 && a.mtg30 <= 2)
  .sort((a,b) => b.eng - a.eng).slice(0, 10);

// Surging: high engagement AND momentum (7d vs 30d ratio > 1.0 = accelerating)
const surging = enriched.filter(a => a.eng >= 65)
  .sort((a,b) => b.momentum - a.momentum || b.eng - a.eng).slice(0, 10);

// Expansion: broad engagement with exec access
const expansion = enriched.filter(a => a.eng >= 50 && a.ppl >= 3 && a.execs >= 1)
  .sort((a,b) => b.ppl - a.ppl || b.eng - a.eng).slice(0, 10);

function fmt(items) {
  if (!items.length) return '_None found._';
  return items.map((a, i) => {
    const lnk = a.pid ? '<https://app.people.ai/account/'+a.pid+'|'+a.name+'>' : '*'+a.name+'*';
    return (i+1)+'. '+lnk+' ('+a.owner+')' + (a.industry ? ' \u2022 '+a.industry : '') + '\n' +
      '    Eng: '+a.eng+' | Mtgs: '+a.mtg30+' ('+a.mtg7+' this wk) | Emails: '+a.emails+
      ' | People: '+a.ppl+' | Execs: '+a.execs+
      ' | Momentum: '+(a.momentum > 1 ? '\ud83d\udcc8 ' : a.momentum < 0.5 ? '\ud83d\udcc9 ' : '')+a.momentum+'x';
  }).join('\n');
}

const date = new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
const text = '\ud83c\udfe2 *Account Insights Digest*\n_'+date+'_\n\n'+
  '\ud83d\udea8 *NEGLECTED ACCOUNTS* \u2014 Low engagement, fading\n'+fmt(neglected)+'\n\n'+
  '\ud83d\udcc8 *SURGING ACCOUNTS* \u2014 Highest momentum\n'+fmt(surging)+'\n\n'+
  '\ud83d\udc8e *EXPANSION CANDIDATES* \u2014 Multi-threaded with exec access\n'+fmt(expansion)+'\n\n'+
  '_'+enriched.length+' accounts analyzed \u2022 People.ai + Claude AI_';
return [{json:{text, responseUrl: $('Parse Command').first().json.responseUrl}}];

function parseCSV(csvData) {
  if (!csvData || !csvData.trim()) return [];
  function parseLine(line) { const v=[]; let q=false,c=''; for(let i=0;i<line.length;i++){const ch=line[i]; if(ch==='"'){q=!q;continue;} if(ch===','&&!q){v.push(c.trim());c='';continue;} c+=ch;} v.push(c.trim()); return v; }
  const lines = csvData.trim().split('\n');
  const h = parseLine(lines[0]);
  console.log('Headers:', h.join(' | '));
  const rows = [];
  for (let i=1; i<lines.length; i++) { const v=parseLine(lines[i]); if(v.length<3)continue; const r={}; h.forEach((hh,idx)=>r[hh]=v[idx]||''); rows.push(r); }
  return rows;
}
const n = s => { const x=Number(String(s||'0').replace(/[,$]/g,'')); return isFinite(x)?x:0; };

const items = $input.all();
const winners = parseCSV(items[0] ? items[0].json.data || '' : '');
const losers = parseCSV(items[1] ? items[1].json.data || '' : '');

function analyze(accs) {
  if (!accs.length) return null;
  const vals = accs.map(a => ({
    eng: n(a['Account Engagement Level']),
    mtg90: n(a['Meetings (Last 90 Days)']), 
    eS: n(a['Emails Sent (Last 90 Days)']), eR: n(a['Emails Received (Last 90 Days)']),
    ppl: n(a['People Engaged (Last 90 Days)']), execs: n(a['Executives Engaged (Last 90 Days)']),
    execActs: n(a['Activities with Executives (C-Level) (Last 90 Days)']),
    industry: a['Industry']||'Unknown', type: a['Account Type']||'Unknown'
  }));
  const avg = fn => Math.round(vals.reduce((s,a)=>s+fn(a),0)/vals.length*10)/10;
  const pct = fn => Math.round(vals.reduce((s,a)=>s+fn(a),0)/vals.length*100);
  // Industry breakdown
  const indMap = {};
  vals.forEach(v => { indMap[v.industry] = (indMap[v.industry]||0)+1; });
  const topInd = Object.entries(indMap).sort((a,b)=>b[1]-a[1]).slice(0,5)
    .map(([ind,ct]) => ind+' ('+Math.round(ct/vals.length*100)+'%)');
  // Account type breakdown
  const typeMap = {};
  vals.forEach(v => { typeMap[v.type] = (typeMap[v.type]||0)+1; });
  const topTypes = Object.entries(typeMap).sort((a,b)=>b[1]-a[1]).slice(0,3)
    .map(([t,ct]) => t+' ('+Math.round(ct/vals.length*100)+'%)');

  return {
    count: accs.length,
    eng: avg(a=>a.eng), mtg90: avg(a=>a.mtg90), 
    emails: avg(a=>a.eS+a.eR), emailsSent: avg(a=>a.eS), emailsRecv: avg(a=>a.eR),
    ppl: avg(a=>a.ppl), execs: avg(a=>a.execs), execActs: avg(a=>a.execActs),
    mtgRatio: pct(a => { const t=a.mtg90+a.eS+a.eR; return t>0?a.mtg90/t:0; }),
    execPct: pct(a => a.ppl>0 ? Math.min(a.execs/a.ppl, 1) : 0),
    respRate: Math.round(vals.reduce((s,a)=>s+(a.eS>0?a.eR/a.eS:0),0)/vals.length*100)/100,

    topInd, topTypes
  };
}

const w = analyze(winners);
const l = analyze(losers);
if (!w || !l) return [{json:{text:'Insufficient data for calibration.',responseUrl:$('Parse Command').first().json.responseUrl}}];

const gap = (wv,lv,s) => { const d=Math.round((wv-lv)*10)/10; return (d>0?'+':'')+d+(s||''); };
const date = new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});

const text = '\ud83c\udfaf *ICP Calibration \u2014 Win Pattern Fingerprint*\n_'+date+'_\n_'+w.count+' won vs '+l.count+' lost (last 90 days, with current engagement > 0)_\n\n'+
  '*\ud83d\udcca Behavioral Benchmarks*\n```\n'+
  'Dimension         | Winners | Losers  | Gap\n'+
  '------------------+---------+---------+---------\n'+
  'Engagement        | '+String(w.eng).padEnd(7)+' | '+String(l.eng).padEnd(7)+' | '+gap(w.eng,l.eng)+'\n'+
  'Meetings (90d)    | '+String(w.mtg90).padEnd(7)+' | '+String(l.mtg90).padEnd(7)+' | '+gap(w.mtg90,l.mtg90)+'\n'+

  'Emails Sent       | '+String(w.emailsSent).padEnd(7)+' | '+String(l.emailsSent).padEnd(7)+' | '+gap(w.emailsSent,l.emailsSent)+'\n'+
  'Emails Received   | '+String(w.emailsRecv).padEnd(7)+' | '+String(l.emailsRecv).padEnd(7)+' | '+gap(w.emailsRecv,l.emailsRecv)+'\n'+
  'People Engaged    | '+String(w.ppl).padEnd(7)+' | '+String(l.ppl).padEnd(7)+' | '+gap(w.ppl,l.ppl)+'\n'+
  'Execs Engaged     | '+String(w.execs).padEnd(7)+' | '+String(l.execs).padEnd(7)+' | '+gap(w.execs,l.execs)+'\n'+
  'Exec Activities   | '+String(w.execActs).padEnd(7)+' | '+String(l.execActs).padEnd(7)+' | '+gap(w.execActs,l.execActs)+'\n'+
  'Meeting Ratio     | '+String(w.mtgRatio+'%').padEnd(7)+' | '+String(l.mtgRatio+'%').padEnd(7)+' | '+gap(w.mtgRatio,l.mtgRatio,'%')+'\n'+
  'Exec % of People  | '+String(w.execPct+'%').padEnd(7)+' | '+String(l.execPct+'%').padEnd(7)+' | '+gap(w.execPct,l.execPct,'%')+'\n'+
  'Email Response    | '+String(w.respRate).padEnd(7)+' | '+String(l.respRate).padEnd(7)+' | '+gap(w.respRate,l.respRate)+'\n'+

  '```\n\n'+
  '*\ud83c\udfc6 Winner Profile*\n'+
  '\u2022 Industries: '+w.topInd.join(', ')+'\n'+
  '\u2022 Account types: '+w.topTypes.join(', ')+'\n'+
  '\u2022 '+w.mtg90+' meetings/90d, '+w.mtgRatio+'% meeting ratio\n'+
  '\u2022 '+w.ppl+' people engaged, '+w.execs+' execs, '+w.execPct+'% exec coverage\n'+
  '\u2022 '+w.respRate+' email response rate ('+w.emailsRecv+' received / '+w.emailsSent+' sent)\n\n'+
  '*\ud83d\udeab Loser Profile*\n'+
  '\u2022 Industries: '+l.topInd.join(', ')+'\n'+
  '\u2022 Account types: '+l.topTypes.join(', ')+'\n'+
  '\u2022 '+l.mtg90+' meetings/90d, '+l.mtgRatio+'% meeting ratio\n'+
  '\u2022 '+l.ppl+' people engaged, '+l.execs+' execs, '+l.execPct+'% exec coverage\n'+
  '\u2022 '+l.respRate+' email response rate\n\n'+
  '*\ud83c\udfaf Key Differentiators* (biggest gaps)\n';

// Sort dimensions by absolute gap to highlight biggest differences
const dims = [
  {name:'Engagement', gap:Math.abs(w.eng-l.eng), desc: w.eng+' vs '+l.eng},
  {name:'Meetings (90d)', gap:Math.abs(w.mtg90-l.mtg90), desc: w.mtg90+' vs '+l.mtg90},
  {name:'Emails Total', gap:Math.abs(w.emails-l.emails), desc: w.emails+' vs '+l.emails},
  {name:'People Engaged', gap:Math.abs(w.ppl-l.ppl), desc: w.ppl+' vs '+l.ppl},
  {name:'Execs Engaged', gap:Math.abs(w.execs-l.execs), desc: w.execs+' vs '+l.execs},
  {name:'Meeting Ratio', gap:Math.abs(w.mtgRatio-l.mtgRatio), desc: w.mtgRatio+'% vs '+l.mtgRatio+'%'},
  {name:'Email Response', gap:Math.abs(w.respRate-l.respRate), desc: w.respRate+' vs '+l.respRate},
  {name:'Momentum', gap:Math.abs(w.momentum-l.momentum), desc: w.momentum+'x vs '+l.momentum+'x'}
].sort((a,b) => b.gap - a.gap);

const topDiffs = dims.slice(0,4).map((d,i) => (i+1)+'. *'+d.name+'*: '+d.desc+' (winners vs losers)').join('\n');

const finalText = text + topDiffs + '\n\n_Filter: accounts with engagement > 0 to ensure current behavioral data \u2022 People.ai + Claude AI_';

return [{json:{text: finalText, responseUrl: $('Parse Command').first().json.responseUrl}}];

function parseCSV(csvData) {
  if (!csvData || !csvData.trim()) return [];
  function parseLine(line) {
    const v = []; let q = false, c = '';
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { q = !q; continue; }
      if (ch === ',' && !q) { v.push(c.trim()); c = ''; continue; }
      c += ch;
    }
    v.push(c.trim());
    return v;
  }
  const lines = csvData.trim().split('\n');
  const headers = parseLine(lines[0]);
  console.log('CSV Headers (' + headers.length + '):', headers.join(' | '));
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const v = parseLine(lines[i]);
    if (v.length < 3) continue;
    const r = {};
    headers.forEach((h, idx) => r[h] = v[idx] || '');
    rows.push(r);
  }
  return rows;
}
const n = s => { const x = Number(String(s || '0').replace(/[,$]/g, '')); return isFinite(x) ? x : 0; };
function getRev(a) {
  // Revenue comes as 3 cols: (amount), (currency), (amount_converted)
  // Use amount first, fall back to amount_converted
  return n(a['Annual Revenue (amount)']) || n(a['Annual Revenue (amount_converted)']) || 0;
}
function fmtRev(v) {
  if (!v) return '';
  if (v >= 1000000000) return '$' + (v/1000000000).toFixed(1) + 'B';
  if (v >= 1000000) return '$' + (v/1000000).toFixed(0) + 'M';
  if (v >= 1000) return '$' + (v/1000).toFixed(0) + 'K';
  return '$' + v;
}
const accs = parseCSV($json.data || '');
if (!accs.length) return [{ json: { text: 'No low-engagement accounts found.', responseUrl: $('Parse Command').first().json.responseUrl } }];

const sorted = accs.map(a => ({
  name: a['Account Name'] || '?',
  owner: a['Account Owner (name)'] || a['Account Owner (id)'] || '?',
  eng: n(a['Account Engagement Level']),
  mtg: n(a['Meetings (Last 30 Days)']),
  rev: getRev(a),
  industry: a['Industry'] || '',
  pid: a['People.ai Internal ID'] || ''
})).sort((a, b) => b.rev - a.rev).slice(0, 15);

function fmt(items) {
  return items.map((a, i) => {
    const lnk = a.pid ? '<https://app.people.ai/account/' + a.pid + '|' + a.name + '>' : '*' + a.name + '*';
    return (i+1) + '. ' + lnk + ' (' + a.owner + ')\n' +
      '    ' + (a.industry || 'No industry') + (a.rev ? ' | ' + fmtRev(a.rev) : '') +
      ' | Eng: ' + a.eng + ' | Mtgs: ' + a.mtg;
  }).join('\n');
}

const date = new Date().toLocaleDateString('en-US', {weekday:'long', month:'long', day:'numeric', year:'numeric'});
const withRev = sorted.filter(a => a.rev > 0);
const noRev = sorted.filter(a => !a.rev);
const text = '\ud83d\ude80 *ICP Target Accounts \u2014 Unengaged Opportunities*\n_' + date + '_\n\n' +
  'Accounts with *near-zero engagement* sorted by revenue. These may match your ICP.\n\n' +
  fmt(sorted) + '\n\n' +
  '_' + accs.length + ' accounts with engagement < 10 \u2022 People.ai + Claude AI_';

return [{ json: { text, responseUrl: $('Parse Command').first().json.responseUrl } }];
